import{_ as t,o as r,c as a,a2 as c}from"./chunks/framework.F7eQ-ohH.js";const n="/bzygq/assets/quesion_imgs_c00363899f8f47639a5cc0cdd61b0614.BLpOzSDT.png",d=JSON.parse('{"title":"2.央国企考试路线&技术路线","description":"","frontmatter":{},"headers":[],"relativePath":"docs/技术路线&考试路线/2.央国企考试路线&技术路线.md","filePath":"docs/技术路线&考试路线/2.央国企考试路线&技术路线.md","lastUpdated":1788881428000}'),o={name:"docs/技术路线&考试路线/2.央国企考试路线&技术路线.md"};function l(i,e,h,p,s,b){return r(),a("div",null,[...e[0]||(e[0]=[c('<h1 id="_2-央国企考试路线-技术路线" tabindex="-1">2.央国企考试路线&amp;技术路线 <a class="header-anchor" href="#_2-央国企考试路线-技术路线" aria-label="Permalink to &quot;2.央国企考试路线&amp;技术路线&quot;">​</a></h1><p><strong>央国企考试路线&amp;技术路线</strong></p><h1 id="央国企考试路线-技术路线" tabindex="-1">央国企考试路线&amp;技术路线 <a class="header-anchor" href="#央国企考试路线-技术路线" aria-label="Permalink to &quot;央国企考试路线&amp;技术路线&quot;">​</a></h1><p><img src="'+n+'" alt=""></p><h2 id="技术路线" tabindex="-1">技术路线 <a class="header-anchor" href="#技术路线" aria-label="Permalink to &quot;技术路线&quot;">​</a></h2><ul><li>中国五矿：<a href="https://wecruit.hotjob.cn/SU62f37858bef57c29ead8adab/pb/custom.html?parentKey=section_hide_1660130532845&amp;pageType=customize_section_hide_1660130532845#/" target="_blank" rel="noreferrer">https://wecruit.hotjob.cn/SU62f37858bef57c29ead8adab/pb/custom.html?parentKey=section_hide_1660130532845&amp;pageType=customize_section_hide_1660130532845#/</a></li><li>中国建筑：<a href="https://recruit.cscec.com/recruit#/index_nav?contract_unit=31997577&amp;company_id=1873" target="_blank" rel="noreferrer">https://recruit.cscec.com/recruit#/index_nav?contract_unit=31997577&amp;company_id=1873</a></li><li>中国电建：<a href="https://zhaopin.powerchina.cn/index" target="_blank" rel="noreferrer">https://zhaopin.powerchina.cn/index</a></li><li>中国核工业集团：<a href="https://cnnc.zhiye.com/" target="_blank" rel="noreferrer">https://cnnc.zhiye.com/</a></li><li>中国兵器装备：<a href="https://www.csgc.com.cn/" target="_blank" rel="noreferrer">https://www.csgc.com.cn/</a></li><li>中国兵器工业：<a href="http://www.norincogroup.com.cn/" target="_blank" rel="noreferrer">http://www.norincogroup.com.cn/</a></li><li>航天科技：<a href="https://www.spacechina.com/n25/index.html" target="_blank" rel="noreferrer">https://www.spacechina.com/n25/index.html</a></li><li>航天科工：<a href="http://www.casic.com.cn/" target="_blank" rel="noreferrer">http://www.casic.com.cn/</a></li><li>中航工业：<a href="https://www.avic.com.cn/" target="_blank" rel="noreferrer">https://www.avic.com.cn/</a></li><li>中国电科：<a href="https://www.cetc.com.cn/" target="_blank" rel="noreferrer">https://www.cetc.com.cn/</a></li><li>中国船舶：<a href="http://www.cssc.net.cn/" target="_blank" rel="noreferrer">http://www.cssc.net.cn/</a></li><li>中国物理工程研究院：<a href="https://zpxx.caep.cn/#/index" target="_blank" rel="noreferrer">https://zpxx.caep.cn/#/index</a></li></ul><p>。。。</p><p>以上这些央企实际上都会招聘一些技术相关的岗位，技术路线其实是投入产出比最高的路线，因为岗位需求无论是国企还是互联网需求都很大。</p><p>即使大家最终的目标是想去一个大央企、大国企，准备技术路线也是没有错的，因为现在大量的传统央企都在做智能化升级，岗位甚至比互联网大厂还多。</p><p>所以即使你是想去央国企，也不要捡了芝麻丢了西瓜，把大量的时间精力投入到行测、申论、408这种适用范围极其窄的路线上。</p><h2 id="考试路线" tabindex="-1">考试路线 <a class="header-anchor" href="#考试路线" aria-label="Permalink to &quot;考试路线&quot;">​</a></h2><ul><li>国家电网：<a href="https://zhaopin.sgcc.com.cn/sgcchr/static/unitPart.html?bullet_id=1d05b1f3d7bd437a90a6e1d14ba626d1" target="_blank" rel="noreferrer">https://zhaopin.sgcc.com.cn/sgcchr/static/unitPart.html?bullet_id=1d05b1f3d7bd437a90a6e1d14ba626d1</a></li><li>中国烟草：<a href="http://www.tobacco.gov.cn/gjyc/zpxx/list.shtml" target="_blank" rel="noreferrer">http://www.tobacco.gov.cn/gjyc/zpxx/list.shtml</a></li><li>中国石油（网站只有秋招和春招的时候才能打开）：<a href="https://zhaopin.cnpc.com.cn/index.html" target="_blank" rel="noreferrer">https://zhaopin.cnpc.com.cn/index.html</a></li><li>中国石化：<a href="http://job.sinopec.com/#/index" target="_blank" rel="noreferrer">http://job.sinopec.com/#/index</a></li><li>中国海油：<a href="https://cnooc.iguopin.com/" target="_blank" rel="noreferrer">https://cnooc.iguopin.com/</a></li><li>中国中铁：<a href="https://rczp.china-railway.com.cn/" target="_blank" rel="noreferrer">https://rczp.china-railway.com.cn/</a></li><li>中国铁建：<a href="https://wecruit.hotjob.cn/SU6125b2ce0dcad4106f124ff0/pb/school.html" target="_blank" rel="noreferrer">https://wecruit.hotjob.cn/SU6125b2ce0dcad4106f124ff0/pb/school.html</a></li><li>国家能源集团：<a href="https://zhaopin.chnenergy.com.cn/planSerch?kinds=3" target="_blank" rel="noreferrer">https://zhaopin.chnenergy.com.cn/planSerch?kinds=3</a></li><li>国家管网集团：<a href="https://wecruit.hotjob.cn/SU617b87702f9d247cb97cc6b7/pb/school.html" target="_blank" rel="noreferrer">https://wecruit.hotjob.cn/SU617b87702f9d247cb97cc6b7/pb/school.html</a></li><li>中粮集团：<a href="https://cofco-campus.zhaopin.com/" target="_blank" rel="noreferrer">https://cofco-campus.zhaopin.com/</a></li><li>中国农业银行：<a href="https://career.abchina.com.cn/build/index.html#/" target="_blank" rel="noreferrer">https://career.abchina.com.cn/build/index.html#/</a></li><li>中国工商银行：<a href="https://job.icbc.com.cn/pc/index.html" target="_blank" rel="noreferrer">https://job.icbc.com.cn/pc/index.html</a></li><li>中国建设银行：<a href="https://job3.ccb.com/cn/job/index.html" target="_blank" rel="noreferrer">https://job3.ccb.com/cn/job/index.html</a></li><li>中国银行：<a href="https://www.boc.cn/aboutboc/bi4/" target="_blank" rel="noreferrer">https://www.boc.cn/aboutboc/bi4/</a></li><li>中国邮政储蓄银行：<a href="https://www.psbc.com/cn/gyyc/rczp/xyzp/" target="_blank" rel="noreferrer">https://www.psbc.com/cn/gyyc/rczp/xyzp/</a></li><li>中国银行：<a href="https://www.boc.cn/aboutboc/bi4/" target="_blank" rel="noreferrer">https://www.boc.cn/aboutboc/bi4/</a></li></ul><p>现在大多数培训机构，对于计算机专业培训的都是考试路线，他们培训这个也没错，但是你光刷行测、申论和408秋招风险很大。</p><p>这个路线适用的企业一个手都能数完，烟草、电网、中石油、国家能投等，而且这几个央企报录比至少都是几千比1的级别，all in考试路线风险极大。</p><p>但是，如果你一心就想上岸，同时考公务员、事业单位啥的，那么all in考试路线也没啥关系，但是真心不建议all in，也不建议报班。</p><p>行测、申论路线自己网上看看免费的视频，刷几套题作为辅助路线的话，完全够了，本来对于大多数人来说也都是陪跑。</p><h2 id="学霸路线" tabindex="-1">学霸路线 <a class="header-anchor" href="#学霸路线" aria-label="Permalink to &quot;学霸路线&quot;">​</a></h2><p>不谈！学霸随意吧～</p><h2 id="the-end" tabindex="-1">The END <a class="header-anchor" href="#the-end" aria-label="Permalink to &quot;The END&quot;">​</a></h2><p>建议大家秋招的时候以技术路线为主，适用范围广：私企、互联、央企、国企都有岗位，我知道现在计算机写代码的岗位卷，但是架不住确实招聘的企业多大，无论什么时候技术路线都应该是主路线。</p><p>考试路线为辅，虽然说计算机专业能报考的体制内岗位和垄断央企的岗位也很多，但是始终是就业面少太多了，不建议all in。如果all in这个的话，要是都考失败了，还会面临真的找不到工作的窘境。</p>',21)])])}const f=t(o,[["render",l]]);export{d as __pageData,f as default};
